import json,numpy as np
c=json.load(open('/app/output/initial/meta.json'))['cameras']['over_shoulder_left_camera'];E=np.array(c['extrinsic_cv']);R=E[:,:3];C=-R.T@E[:,3];K=np.array(c['intrinsic_cv'])
for uv in [(570,515),(570,520),(585,520),(600,520),(525,450),(520,460),(635,570),(600,575)]:
 d=R.T@np.linalg.inv(K)@np.array([*uv,1]);
 for z in [0,.05,.1]:
  p=C+d*((z-C[2])/d[2]);
  if z==.05: print(uv,'at.05',p[:2].round(3))
